//! AC2/AC3: projection parser, fingerprint and atomic writer parity.
//!
//! Expected values are generated by `tests/generate_rust_store_fixture.py` from
//! the REAL Python `share/broker_protocol.parse_projection_payload`,
//! `share/management._fingerprint` and `share/secret_protection` (AES-GCM).

use std::path::PathBuf;

use serde_json::Value;
use um_store::projection::{parse_projection_payload, ProjectionError};
use um_store::secret::{
    mask_secret, protect_with_nonce, secret_hash, unprotect_with_key,
};
use um_store::{AllowPath, DenyAll, ProtectedProjectionWriter};

fn fixture() -> Value {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../..")
        .join("tests/fixtures/rust_store_rev1.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn projection_error(error: ProjectionError) -> Value {
    serde_json::json!({"code": error.code, "message": error.message})
}

#[test]
fn the_shared_projection_parser_matches_python() {
    let fixture = fixture();
    for case in fixture["projection"]["accepted"].as_array().unwrap() {
        let parsed = parse_projection_payload(&case["input"]).unwrap();
        assert_eq!(&parsed, &case["output"], "accepted projection differs");
        assert_eq!(
            um_store::fingerprint(&case["input"]),
            case["fingerprint"].as_str().unwrap(),
            "projection fingerprint differs from Python"
        );
    }
    for case in fixture["projection"]["rejected"].as_array().unwrap() {
        let error = parse_projection_payload(&case["input"]).unwrap_err();
        assert_eq!(
            projection_error(error),
            serde_json::json!({
                "code": case["code"],
                "message": case["message"],
            }),
            "rejected projection differs"
        );
    }
}

#[test]
fn the_posix_secret_scheme_round_trips_python_blobs() {
    let fixture = fixture();
    for vector in fixture["secret_vectors"].as_array().unwrap() {
        let key = hex::decode(vector["key_hex"].as_str().unwrap()).unwrap();
        let nonce_hex = vector["nonce_hex"].as_str().unwrap();
        let mut nonce = [0u8; 12];
        nonce.copy_from_slice(&hex::decode(nonce_hex).unwrap());
        let plaintext = vector["plaintext"].as_str().unwrap();
        let blob = hex::decode(vector["blob_hex"].as_str().unwrap()).unwrap();
        assert_eq!(
            unprotect_with_key(&blob, "aesgcm-file-key-v1", &key).unwrap(),
            plaintext
        );
        assert_eq!(
            hex::encode(protect_with_nonce(plaintext, &key, &nonce).unwrap()),
            vector["blob_hex"].as_str().unwrap()
        );
        assert_eq!(secret_hash(plaintext), vector["hash"].as_str().unwrap());
        assert_eq!(mask_secret(plaintext), vector["mask"].as_str().unwrap());
    }
    let first = &fixture["secret_vectors"][0];
    let blob = hex::decode(first["blob_hex"].as_str().unwrap()).unwrap();
    let key = hex::decode(first["key_hex"].as_str().unwrap()).unwrap();
    assert_eq!(
        unprotect_with_key(&blob, "dpapi-user-scope-v1", &key)
            .unwrap_err()
            .kind(),
        "SecretUndecryptable"
    );
    assert_eq!(
        unprotect_with_key(&blob[..20], "aesgcm-file-key-v1", &key)
            .unwrap_err()
            .kind(),
        "SecretUndecryptable"
    );
}

#[test]
fn the_protected_writer_replaces_atomically_and_refuses_regressions() {
    let fixture = fixture();
    let case = &fixture["projection"]["accepted"][0];
    let projection = case["output"].clone();
    let directory = tempfile::tempdir().unwrap();
    let path = directory.path().join("share-projection.json");
    let mut writer = ProtectedProjectionWriter::new(path.clone(), AllowPath(path.clone())).unwrap();
    let generation = projection["config_generation"].as_i64().unwrap();
    let fingerprint = um_store::fingerprint(&projection);
    let written = writer
        .write(&projection, generation, &fingerprint)
        .unwrap();
    assert_eq!(written, fingerprint);
    let reread: Value =
        serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    assert_eq!(reread, projection);

    let mut older = projection.clone();
    older["config_generation"] = Value::from(generation - 1);
    let older_fingerprint = um_store::fingerprint(&older);
    assert_eq!(
        writer
            .write(&older, generation - 1, &older_fingerprint)
            .unwrap_err()
            .code,
        "bad_request",
        "an older generation must be refused"
    );

    let mut changed = projection.clone();
    changed["share_max_concurrency"] = Value::from(1);
    let changed_fingerprint = um_store::fingerprint(&changed);
    assert_eq!(
        writer
            .write(&changed, generation, &changed_fingerprint)
            .unwrap_err()
            .code,
        "bad_request",
        "same-generation different content must be refused"
    );
    let unchanged: Value =
        serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    assert_eq!(unchanged, projection);
}

#[test]
fn the_protected_writer_refuses_a_corrupt_baseline_and_a_denied_acl() {
    let fixture = fixture();
    let projection = fixture["projection"]["accepted"][0]["output"].clone();
    let generation = projection["config_generation"].as_i64().unwrap();
    let fingerprint = um_store::fingerprint(&projection);

    let directory = tempfile::tempdir().unwrap();
    let corrupt = directory.path().join("corrupt.json");
    std::fs::write(&corrupt, "{\"schema_version\": 2").unwrap();
    let error = match ProtectedProjectionWriter::new(
        corrupt.clone(),
        AllowPath(corrupt.clone()),
    ) {
        Ok(_) => panic!("a corrupt baseline must refuse publication"),
        Err(error) => error,
    };
    assert_eq!(error.code, "bad_request");
    assert_eq!(std::fs::read_to_string(&corrupt).unwrap(), "{\"schema_version\": 2");

    let denied_path = directory.path().join("denied.json");
    let mut denied = ProtectedProjectionWriter::new(
        denied_path.clone(),
        DenyAll,
    )
    .unwrap();
    let error = denied
        .write(&projection, generation, &fingerprint)
        .unwrap_err();
    assert_eq!(error.code, "bad_request");
    assert!(!denied_path.exists(), "a refused write must leave no file");
}

#[test]
fn the_writer_refuses_a_projection_the_parser_rejects() {
    let fixture = fixture();
    let case = &fixture["projection"]["accepted"][0];
    let projection = case["output"].clone();
    let directory = tempfile::tempdir().unwrap();
    let path = directory.path().join("share-projection.json");
    let mut writer = ProtectedProjectionWriter::new(path.clone(), AllowPath(path)).unwrap();
    let mut invalid = projection.clone();
    invalid["data"][0]["max_concurrency"] = Value::from(65);
    let generation = invalid["config_generation"].as_i64().unwrap();
    let fingerprint = um_store::fingerprint(&invalid);
    let error = writer
        .write(&invalid, generation, &fingerprint)
        .unwrap_err();
    assert_eq!(error.code, "bad_request");
    assert!(!directory
        .path()
        .join("share-projection.json")
        .exists());
}
